// Token Radar v7 — the page, compact layout. Reads window.EVIDENCE + window.ROWS
// (evidence.js, generated by this run), recomputes the derived numbers from the
// same formulas lib/model.ts uses, and renders the board, the farm plans, the
// model evidence and the coverage.
//
// ROW order: [rank, slug, name, category, chain, tvl, change7d, age,
// watchlist 0/1, kin 0/1, kin name, implied, ev, odds, band lo, band hi,
// verdict 0/1/2] (0 FARM, 1 MARGINAL, 2 SKIP).
// Screenshot helpers (?shot=board|farms|model|detail&slug=...) only choose what
// the capture shows; the page works the same without them.
(function () {
  var E = window.EVIDENCE, ROWS = window.ROWS;
  var V = ['FARM', 'MARGINAL', 'SKIP'];
  function $(id) { return document.getElementById(id); }
  function esc(s) { return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
  function money(n) { return '$' + Math.round(n).toLocaleString('en-US'); }
  function moneyM(n) { return '$' + (n / 1e6).toFixed(1) + 'M'; }
  function pct(x, d) { return (x * 100).toFixed(d === undefined ? 1 : d) + '%'; }
  function signed(n) { return (n >= 0 ? '+' : '') + money(n); }
  function kv(k, v) { return '<dt>' + esc(k) + '</dt><dd>' + esc(v) + '</dd>'; }
  function tableHtml(head, rows, numFrom) {
    var isWhy = head[head.length - 1] === 'Why';
    function cellCls(i, last) {
      if (last && isWhy) return ' class="why"';
      return i >= numFrom ? ' class="num"' : '';
    }
    var h = '<table class="mini"><thead><tr>' + head.map(function (c, i) { return '<th' + cellCls(i, i === head.length - 1) + '>' + esc(c) + '</th>'; }).join('') + '</tr></thead><tbody>';
    h += rows.map(function (r) {
      return '<tr>' + r.map(function (c, i) { return '<td' + cellCls(i, i === r.length - 1) + '>' + esc(c) + '</td>'; }).join('') + '</tr>';
    }).join('');
    return h + '</tbody></table>';
  }
  function norm(r) {
    return { rank: r[0], slug: r[1], name: r[2], cat: r[3] || null, chain: r[4], tvl: r[5], chg: r[6], age: r[7], wl: !!r[8], kin: !!r[9], kinName: r[10] || null, implied: r[11], ev: r[12], odds: r[13], bandLo: r[14], bandHi: r[15], verdict: V[r[16]] };
  }
  var rows = ROWS.map(norm);
  var bySlug = {};
  rows.forEach(function (r) { bySlug[r.slug] = r; });
  var q25 = E.honesty.q25, q75 = E.honesty.q75;
  function dropOf(r) { return Math.round((r.ev * 0.07 * 2000) / (0.1 * r.tvl) * 100) / 100; }
  function netOf(r) { return Math.round((dropOf(r) - 11) * 100) / 100; }
  function rangeLo(r) { return Math.max(1, Math.round(r.implied * Math.pow(10, q25))); }
  function rangeHi(r) { return Math.max(1, Math.round(r.implied * Math.pow(10, q75))); }
  var holdUntil = (function () { var d = new Date(E.asOf + 'T00:00:00Z'); d.setUTCDate(d.getUTCDate() + 364); return d.toISOString().slice(0, 10); })();

  // The farm plan: the same eight steps lib/model.ts writes into board.json,
  // generated here from the same inputs so the page and the board agree.
  function actionFor(r) {
    var c = (r.cat || '').toLowerCase(), n = r.name, ch = r.chain || 'its main chain';
    if (c.indexOf('lend') >= 0 || c.indexOf('cdp') >= 0 || c.indexOf('collateral') >= 0) return 'Supply $2,000 of USDC to ' + n + ' on ' + ch + ' and keep the position open.';
    if (c.indexOf('dex') >= 0 || c.indexOf('yield') >= 0 || c.indexOf('leveraged farm') >= 0) return 'Provide $2,000 of liquidity to ' + n + "'s main pool on " + ch + ' and keep the position open.';
    if (c.indexOf('bridge') >= 0) return 'Bridge $2,000 of USDC to ' + ch + ' through ' + n + ' and use the bridged funds in its app.';
    if (c.indexOf('staking') >= 0 || c.indexOf('restak') >= 0) return 'Stake $2,000 of the chain' + "'s staking asset through " + n + ' and keep the receipt.';
    if (c.indexOf('perpetual') >= 0 || c.indexOf('derivative') >= 0) return 'Deposit $2,000 of USDC as margin on ' + n + ' and open one small hedge.';
    if (c.indexOf('prediction') >= 0) return 'Fund $2,000 and place one market position on ' + n + '.';
    if (c.indexOf('curator') >= 0 || c.indexOf('allocator') >= 0) return 'Deposit $2,000 into a ' + n + ' vault on ' + ch + ' and keep the shares.';
    if (c.indexOf('stable') >= 0) return 'Mint or deposit $2,000 of the stable asset through ' + n + ' on ' + ch + '.';
    if (c.indexOf('rwa') >= 0) return 'Mint $2,000 of the protocol' + "'s yield asset on " + ch + ' and hold it.';
    if (c.indexOf('insurance') >= 0) return 'Buy $2,000 of cover from ' + n + ' on ' + ch + ' and keep the policy.';
    return 'Deposit $2,000 of USDC into ' + n + ' on ' + ch + ' and keep the position open.';
  }
  function farmSteps(r) {
    var net = netOf(r), drop = dropOf(r);
    var word = net >= 10 ? 'a farm' : net >= 0 ? 'a thin farm' : 'not a farm on these numbers';
    var steps = [
      ['Use a fresh wallet that holds only the funds you plan to farm, and keep its seed phrase offline.', 'under $3 of gas for the first transaction', '5 minutes'],
      [actionFor(r), '$2,000 of capital and about $8 of gas', '15 minutes to set up'],
      ['Make one qualifying action each week, such as a deposit, a borrow, a swap or a vote.', 'about $2 of gas a week', '10 minutes a week'],
      ['Hold the position for at least 52 weeks so the activity is counted in more than one snapshot, until ' + holdUntil + '.', 'the $2,000 stays in the position', '52 weeks'],
      ['This board prices the position at an expected drop of $' + drop.toFixed(2) + ' against $11 of gas, a net of $' + net.toFixed(2) + ' — ' + word + '.', 'the $11 of gas is already counted', 'read the board before you start'],
      ['Before you withdraw, open the protocol' + "'s own points or rewards page and claim only from the link it publishes.", 'no fee to check, and never pay to claim', '10 minutes'],
      ['If the protocol records a token before the 52 weeks are up, check the claim window at once — airdrop claims expire.', 'nothing but the check', '10 minutes'],
      ['Write the wallet, the dates and every transaction in a farm log so you can repeat the position or unwind it.', 'nothing but the log', '5 minutes'],
    ];
    return steps.map(function (s) { var t = s[0] + ' Cost: ' + s[1] + '. Time: ' + s[2] + '.'; return t.length > 600 ? t.slice(0, 596) + '...' : t; });
  }

  // ---- header strips (all numbers from the run's own evidence) ----
  var ageRow = null, baseRow = null, kinRow = null;
  E.oddsTests.forEach(function (t) {
    if (t.term === 'age (log10 days)') ageRow = t;
    if (t.term === 'base rate only') baseRow = t;
    if (t.term === 'age + growth + kin') kinRow = t;
  });
  $('kpis').innerHTML =
    '<div class="kpi-card"><b>x' + E.valueLoo + '</b><span>Value LOO · 90 comps</span></div>' +
    '<div class="kpi-card"><b>x' + E.valueWf + '</b><span>Value walk-forward · 3 splits</span></div>' +
    '<div class="kpi-card"><b>x' + E.valueCv + '</b><span>Value 5-fold CV · ×5 seeds</span></div>' +
    '<div class="kpi-card"><b>' + ageRow.loo + '</b><span>Odds Brier LOO · n=' + E.oddsPop + '</span></div>' +
    '<div class="kpi-card"><b>' + ageRow.wf + '</b><span>Odds Brier WF · beats base</span></div>' +
    '<div class="kpi-card"><b>' + E.coverage.ranked + ' / ' + E.coverage.scanned + '</b><span>Board · ' + E.coverage.watchlistCovered + '/' + E.coverage.watchlist + ' watchlist</span></div>' +
    '<div class="kpi-card"><b>' + E.farmCounts.farm + ' FARM</b><span>' + E.farmCounts.marginal + ' marginal · ' + E.farmCounts.skip + ' skip</span></div>' +
    '<div class="kpi-card"><b>' + moneyM(E.topRow.implied) + '</b><span>' + esc(E.topRow.name) + '</span></div>';
  $('bestfarms').innerHTML = E.bestFarms.map(function (f) {
    return '<div class="farm-card"><b>+' + money(f.net) + ' net</b><span>' + esc(f.name) + ' · ' + moneyM(f.implied) + ' · odds ' + f.odds + ' · EV ' + moneyM(f.ev) + '</span></div>';
  }).join('');
  $('integrity').innerHTML = '<b>Integrity strip —</b> ' + E.selfTest.map(esc).join(' · ');
  (function () {
    var c = E.coverage;
    function seg(n, cls, label) { var p = n / c.scanned; return '<div class="' + cls + '" style="flex:' + n + '">' + (p >= 0.04 ? label : '') + '</div>'; }
    $('accounting').innerHTML = '<div class="acct-bar">' + seg(c.ranked, 'seg-ranked', 'ranked ' + c.ranked) + seg(c.liveWithMcap, 'seg-live', 'live ' + c.liveWithMcap) + seg(c.tokenRecordedNoCap, 'seg-nocap', 'token, no cap ' + c.tokenRecordedNoCap) + seg(c.tokenRecordedZeroCap, 'seg-zero', 'zero cap ' + c.tokenRecordedZeroCap) + seg(c.preTokenNotRanked, 'seg-notranked', 'pre-token, not ranked ' + c.preTokenNotRanked) + '</div>';
  })();

  // ---- held-out evidence, on the board tab (short form, from the evidence) ----
  (function () {
    var kept = E.valueTests.filter(function (t) { return t.kept; })[0];
    var cats = E.valueTests.filter(function (t) { return t.term.indexOf('category') === 0; });
    var control = E.valueTests.filter(function (t) { return t.term.indexOf('CONTROL') === 0; })[0];
    var short = [kept].concat(cats).concat([control]);
    $('value-proof').innerHTML = tableHtml(['Term', 'LOO', 'WF', 'Kept?'], short.map(function (t) {
      return [t.term, 'x' + t.loo, 'x' + t.wf, t.kept ? 'KEPT' : 'no'];
    }), 1);
    var win = ((kept.loo - control.loo) / kept.loo * 100).toFixed(1);
    $('value-proof-note').textContent = 'Kept only if it beats size-only on BOTH tests by ≥1% — nothing did; the control "wins" LOO by ' + win + '% and still fails.';
    $('odds-proof').innerHTML = tableHtml(['Term', 'LOO Brier', 'WF Brier', 'Kept?'], [ageRow, kinRow, baseRow].map(function (t) {
      return [t.term, t.loo, t.wf, t.kept ? 'KEPT' : 'no'];
    }), 1);
    $('odds-proof-note').textContent = 'Age beats the base rate on both tests; the kin term is a separation artifact (8 kin, 0 listed).';
    var h = E.honesty;
    $('honesty-proof').innerHTML = '<div class="honest-grid">' +
      '<div class="honest-cell"><b>' + pct(h.loo2575) + '</b><span>LOO P25–P75 · 50%</span></div>' +
      '<div class="honest-cell"><b>' + pct(h.loo1090) + '</b><span>LOO P10–P90 · 80%</span></div>' +
      '<div class="honest-cell"><b>' + pct(h.wf2575) + '</b><span>WF P25–P75 · 50%</span></div>' +
      '<div class="honest-cell"><b>' + pct(h.wf1090) + '</b><span>WF P10–P90 · 80%' + (h.wf1090 < 0.8 ? ' · narrow' : '') + '</span></div></div>';
  })();

  // ---- board table ----
  var sortKey = 'rank', sortDir = 1;
  var sortFns = { rank: function (a, b) { return a.rank - b.rank; }, name: function (a, b) { return a.name < b.name ? -1 : 1; }, tvl: function (a, b) { return a.tvl - b.tvl; }, age: function (a, b) { return (a.age || 0) - (b.age || 0); }, implied: function (a, b) { return a.implied - b.implied; }, odds: function (a, b) { return a.odds - b.odds; }, ev: function (a, b) { return a.ev - b.ev; }, net: function (a, b) { return netOf(a) - netOf(b); }, verdict: function (a, b) { return a.verdict < b.verdict ? -1 : 1; } };
  var cats = [];
  rows.forEach(function (r) { if (r.cat && cats.indexOf(r.cat) < 0) cats.push(r.cat); });
  cats.sort();
  $('f-cat').innerHTML = '<option value="">all</option>' + cats.map(function (c) { return '<option>' + esc(c) + '</option>'; }).join('');
  function filtered() {
    var v = $('f-verdict').value, c = $('f-cat').value, w = $('f-watch').checked, q = ($('f-q').value || '').toLowerCase();
    var list = rows.filter(function (r) {
      return (!v || r.verdict === v) && (!c || r.cat === c) && (!w || r.wl) && (!q || r.name.toLowerCase().indexOf(q) >= 0 || r.slug.indexOf(q) >= 0);
    });
    list.sort(function (a, b) { return sortFns[sortKey](a, b) * sortDir; });
    return list;
  }
  function renderBoard() {
    var list = filtered();
    $('rowcount').textContent = list.length + ' of ' + rows.length + ' rows (sorted by ' + sortKey + ')';
    $('board').querySelector('tbody').innerHTML = list.map(function (r) {
      return '<tr data-slug="' + esc(r.slug) + '"><td class="num">' + r.rank + '</td><td><b>' + esc(r.name) + '</b><br><span class="sub">' + esc(r.cat || 'no category') + ' · ' + esc(r.chain || '—') + (r.wl ? ' · watchlist' : '') + (r.kin ? ' · kin: ' + esc(r.kinName) : '') + '</span></td>' +
        '<td class="num">' + moneyM(r.tvl) + '</td><td class="num">' + (r.age === null ? '—' : r.age + 'd') + '</td>' +
        '<td class="num">' + money(r.implied) + '<br><span class="sub">' + money(rangeLo(r)) + '–' + money(rangeHi(r)) + '</span></td>' +
        '<td class="num">' + r.odds.toFixed(3) + '</td><td class="num">' + money(r.ev) + '</td>' +
        '<td class="num">' + signed(netOf(r)) + '</td><td><span class="badge ' + r.verdict + '">' + r.verdict + '</span></td></tr>';
    }).join('');
  }
  function showDetail(r, el) {
    var steps = farmSteps(r);
    el.innerHTML = '<h3>#' + r.rank + ' ' + esc(r.name) + ' <span class="badge ' + r.verdict + '">' + r.verdict + '</span></h3>' +
      '<div class="meta">' + esc(r.cat || 'no category') + ' · ' + esc(r.chain || '—') + ' · TVL ' + money(r.tvl) + ' · age ' + (r.age === null ? 'unknown' : r.age + ' days') + (r.wl ? ' · on the watchlist' : '') + (r.kin ? ' · family token: ' + esc(r.kinName) : '') + '<br>' +
      'Implied value ' + money(r.implied) + ' (range ' + money(rangeLo(r)) + '–' + money(rangeHi(r)) + ', rank band ' + r.bandLo + '–' + r.bandHi + ') · 24-month odds ' + r.odds.toFixed(3) + ' · expected value ' + money(r.ev) + ' · own-token share 100%<br>' +
      'Farm: $2,000 in, expected drop ' + money(dropOf(r)) + ', gas $11, net ' + signed(netOf(r)) + ', hold until ' + holdUntil + (netOf(r) >= 0 ? ', break-even ' + holdUntil : ', never breaks even on these numbers') + '</div>' +
      '<div class="steps"><b>Farm plan — eight steps:</b><ol>' + steps.map(function (s) { return '<li>' + esc(s) + '</li>'; }).join('') + '</ol></div>';
  }
  $('board').querySelector('tbody').addEventListener('click', function (e) { var tr = e.target.closest('tr'); if (tr) showDetail(bySlug[tr.getAttribute('data-slug')], $('detail')); });
  $('board').querySelectorAll('th[data-sort]').forEach(function (th) {
    th.addEventListener('click', function () { var k = th.getAttribute('data-sort'); if (sortKey === k) sortDir = -sortDir; else { sortKey = k; sortDir = 1; } renderBoard(); });
  });
  ['f-verdict', 'f-cat', 'f-watch', 'f-q'].forEach(function (id) { $(id).addEventListener('input', renderBoard); });
  renderBoard();
  showDetail(rows[0], $('detail'));

  // ---- farms tab ----
  (function () {
    var farms = rows.filter(function (r) { return r.verdict === 'FARM'; }).sort(function (a, b) { return netOf(b) - netOf(a); });
    $('farmstable').querySelector('tbody').innerHTML = farms.map(function (r) {
      return '<tr data-slug="' + esc(r.slug) + '"><td class="num">' + r.rank + '</td><td><b>' + esc(r.name) + '</b></td><td class="num">' + moneyM(r.tvl) + '</td><td class="num">' + money(r.implied) + '</td><td class="num">' + r.odds.toFixed(3) + '</td><td class="num">' + money(r.ev) + '</td><td class="num">' + money(dropOf(r)) + '</td><td class="num">+' + money(netOf(r)) + '</td></tr>';
    }).join('');
    $('farmstable').querySelector('tbody').addEventListener('click', function (e) { var tr = e.target.closest('tr'); if (tr) showDetail(bySlug[tr.getAttribute('data-slug')], $('farmdetail')); });
    if (farms[0]) showDetail(farms[0], $('farmdetail'));
  })();

  // ---- model tab ----
  $('value-model').innerHTML = 'log10(mcap) = ' + E.valueBeta[0] + ' + ' + E.valueBeta[1] + ' x log10(TVL) · slope ' + E.valueBeta[1] + ' ± ' + E.valueBetaSe[1] + ' (bootstrap SE, 200 refits) · intercept ' + E.valueBeta[0] + ' ± ' + E.valueBetaSe[0] + ' · median miss LOO x' + E.valueLoo + ' · walk-forward x' + E.valueWf + ' · 5-fold CV x' + E.valueCv + ' · flat multiple rival x' + E.flatRival.loo + ' LOO / x' + E.flatRival.wf + ' WF at multiple ' + E.flatRival.multiple + ' — the size curve beats it ' + (E.flatRival.loo / E.valueLoo).toFixed(1) + 'x on LOO';
  $('value-table').innerHTML = tableHtml(['Term', 'LOO', 'WF', 'CV', 'Win share', 'Kept?'], E.valueTests.map(function (t) { return [t.term, 'x' + t.loo, 'x' + t.wf, 'x' + t.cv, t.winShare, t.kept ? 'KEPT' : 'no']; }), 1);
  $('odds-model').innerHTML = 'logit P(listed by age A) = ' + E.oddsBeta[0] + ' + ' + E.oddsBeta[1] + ' x log10(age) · age coefficient ' + E.oddsBeta[1] + ' ± ' + E.oddsBetaSe[1] + ' (bootstrap SE, 200 refits) · population ' + E.oddsPop + ' protocols with age &gt;= 730 days (outcome known); base rate ' + E.oddsBaseRate + ', base Brier ' + E.oddsBaseBrier + ' · 200-split win share ' + E.oddsAgeWinShare + ' vs the base rate · odds(A) = [F(730) - F(A)] / [1 - F(A)]: the chance a protocol still tokenless at age A records one within its first 24 months';
  $('odds-table').innerHTML = tableHtml(['Term', 'LOO Brier', 'LOO base', 'WF Brier', 'WF base', 'Kept?', 'Why'], E.oddsTests.map(function (t) { return [t.term, t.loo, t.looBase, t.wf, t.wfBase, t.kept ? 'KEPT' : 'no', t.note || '']; }), 1);
  (function () {
    var h = E.honesty;
    $('honesty').innerHTML = '<dl class="kv">' +
      kv('Inside P25–P75, leave-one-out', pct(h.loo2575) + ' (stated 50%)') +
      kv('Inside P10–P90, leave-one-out', pct(h.loo1090) + ' (stated 80%)') +
      kv('Inside P25–P75, walk-forward', pct(h.wf2575) + ' (stated 50%)') +
      kv('Inside P10–P90, walk-forward', pct(h.wf1090) + ' (stated 80%)') +
      kv('Range factors', 'P25 x' + Math.pow(10, h.q25).toFixed(2) + ' · P75 x' + Math.pow(10, h.q75).toFixed(2)) +
      '</dl>';
  })();
  (function () {
    var pts = E.oddsAt;
    var W = 640, H = 104, L = 34, R = 10, T = 8, B = 18;
    var xs = pts.map(function (p) { return Math.log10(p[0]); });
    var x0 = Math.log10(30), x1 = Math.log10(1460), yMax = 0.14;
    function X(a) { return L + (Math.log10(a) - x0) / (x1 - x0) * (W - L - R); }
    function Y(o) { return T + (1 - o / yMax) * (H - T - B); }
    var s = '<svg viewBox="0 0 ' + W + ' ' + H + '" preserveAspectRatio="none">';
    [0, 0.05, 0.1].forEach(function (g) {
      s += '<line x1="' + L + '" y1="' + Y(g) + '" x2="' + (W - R) + '" y2="' + Y(g) + '" stroke="#21262d"/>';
      s += '<text x="' + (L - 4) + '" y="' + (Y(g) + 3) + '" fill="#8b949e" font-size="9" text-anchor="end">' + g.toFixed(2) + '</text>';
    });
    [30, 100, 365, 730, 1460].forEach(function (a) {
      s += '<text x="' + X(a) + '" y="' + (H - 5) + '" fill="#8b949e" font-size="9" text-anchor="middle">' + (a >= 365 ? Math.round(a / 365 * 10) / 10 + 'y' : a + 'd') + '</text>';
    });
    s += '<polyline fill="none" stroke="#58a6ff" stroke-width="2" points="' + pts.map(function (p) { return X(p[0]).toFixed(1) + ',' + Y(p[1]).toFixed(1); }).join(' ') + '"/>';
    pts.forEach(function (p) {
      s += '<circle cx="' + X(p[0]).toFixed(1) + '" cy="' + Y(p[1]).toFixed(1) + '" r="3" fill="#58a6ff"/>';
      if (p[1] > 0.01) s += '<text x="' + X(p[0]).toFixed(1) + '" y="' + (Y(p[1]) - 6).toFixed(1) + '" fill="#e6edf3" font-size="9" text-anchor="middle">' + p[1] + '</text>';
    });
    s += '<text x="' + X(730).toFixed(1) + '" y="' + (Y(0.001) - 6).toFixed(1) + '" fill="#8b949e" font-size="9" text-anchor="middle">0.001</text>';
    s += '</svg>';
    $('odds-curve').innerHTML = s;
  })();
  $('cohorts').innerHTML = tableHtml(['Listed', 'n', 'With token', 'Rate'], E.cohortByYear.map(function (c) { return [c.label, c.n, c.listed, c.rate]; }), 1) +
    '<br>' + tableHtml(['Age band', 'n', 'With token', 'Share'], E.cohortByAgeBand.map(function (c) { return [c.label, c.n, c.listed, c.rate]; }), 1);
  (function () {
    var sink = E.oddsTests.filter(function (t) { return t.term === 'age + growth + kin + size'; })[0];
    var vControl = E.valueTests.filter(function (t) { return t.term.indexOf('CONTROL') === 0; })[0];
    var oControl = E.oddsTests.filter(function (t) { return t.term.indexOf('CONTROL') === 0; })[0];
    var kept = E.valueTests.filter(function (t) { return t.kept; })[0];
    $('rivals').innerHTML = '<dl class="kv">' +
      kv('Flat multiple (value)', 'LOO x' + E.flatRival.loo + ' / WF x' + E.flatRival.wf + ' — worse than the size curve on both tests') +
      kv('Kitchen-sink odds (age+growth+kin+size)', 'LOO ' + sink.loo + ' / WF ' + sink.wf + ' — beats age alone on both tests, but only through the kin term: 8 kin protocols, 0 listed in the clean population, so the coefficient runs to about -12 and is not identified. It would zero out the board\'s 8 kin rows on n=8 evidence, so it is not kept.') +
      kv('Control (another row\'s growth)', 'value LOO x' + vControl.loo + ' vs size-only x' + kept.loo + '; odds LOO ' + oControl.loo + ' — a nonsense term that "wins" LOO proves the noise floor, not a model') +
      '</dl>';
  })();
  $('pipeline').innerHTML = '<dl class="kv">' +
    kv('With a token recorded', E.comps.recorded) +
    kv('With a usable cap (mcap > 0)', E.comps.usableCap) +
    kv('One per ticker symbol', E.comps.onePerTicker) +
    kv('Dated (listed_at known)', E.comps.dated) +
    kv('Kept after dropping mcap/TVL > 10', E.comps.kept + ' (' + E.comps.droppedRatio.join(', ') + ' dropped)') +
    '</dl>';

  // ---- coverage tab ----
  (function () {
    var c = E.coverage;
    $('coverage').innerHTML = '<dl class="kv">' +
      kv('Protocols scanned', c.scanned) +
      kv('Ranked on the board', c.ranked) +
      kv('Live with a market cap', c.liveWithMcap + ' (shown at the market\'s own values, never ranked)') +
      kv('Token recorded, no cap', c.tokenRecordedNoCap) +
      kv('Token recorded, zero/negative cap', c.tokenRecordedZeroCap) +
      kv('Pre-token, not ranked', c.preTokenNotRanked + ' (below the floor and not in the early radar)') +
      kv('Watchlist', c.watchlistCovered + ' of ' + c.watchlist + ' covered') +
      '</dl>';
    $('coverage-note').textContent = 'The watchlist is the floor, never the ceiling: the board ranks ' + (c.ranked - c.watchlist) + ' pre-token protocols below the $50M floor as well as all ' + c.watchlist + ' on it. Live-token protocols are set aside and shown at the market\'s own values, never mixed into the ranking.';
  })();
  $('asof').textContent = E.asOf;

  // ---- tabs + screenshot helpers ----
  function showTab(name) {
    document.querySelectorAll('nav button').forEach(function (b) { b.classList.toggle('on', b.getAttribute('data-tab') === name); });
    document.querySelectorAll('.tab').forEach(function (t) { t.classList.toggle('on', t.id === 'tab-' + name); });
  }
  document.querySelectorAll('nav button').forEach(function (b) { b.addEventListener('click', function () { showTab(b.getAttribute('data-tab')); }); });
  var q = new URLSearchParams(location.search);
  var shot = q.get('shot');
  if (shot === 'farms') showTab('farms');
  else if (shot === 'model') showTab('model');
  else if (shot === 'coverage') showTab('coverage');
  else if (shot === 'detail') { var r = bySlug[q.get('slug')] || rows[0]; showDetail(r, $('detail')); document.body.classList.add('shot-detail'); }
})();
